-- estruturas negativas e interrogativas formais, be going to
-- em textos de política comparada, sínteses e conclusões TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'be-going-to';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo be-going-to não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Be going to — formas negativas e interrogativas formais
  (cid,71,229,'gap_fill','_____ the proposed framework _____ (address) _____ structural inequities that _____ (persist) for decades, or _____ (it/merely/replicate) _____ existing patterns under _____ new institutional form?','Is / going to address / the / have persisted / is it merely going to replicate / the / a',NULL,'Interrogative ''is going to address'' + negative rhetorical ''is it merely going to replicate.''','hard'),
  (cid,71,230,'gap_fill','_____ reforms _____ (not/succeed) without _____ genuine commitment from _____ stakeholders who _____ (most/affect/passive) by _____ changes — _____ (be/this) _____ kind of commitment _____ government _____ (willing) _____ (provide)?','The / are not going to succeed / a / the / are most affected / the / Is this / the / the / is willing to / provide',NULL,'Negative ''are not going to succeed'' + interrogative about commitment.','hard'),
  (cid,71,231,'multiple_choice','Which interrogative form CORRECTLY uses ''be going to'' in a formal policy question?','Is the proposed legislation going to achieve the reductions in carbon emissions that the government has promised?','[''Will the proposed legislation achieve the reductions promised?'',''Is the proposed legislation going to achieve the reductions in carbon emissions that the government has promised?'',''Does the proposed legislation achieve the promised reductions?'',''Has the proposed legislation achieved the promised reductions?'']','''Is going to achieve'' = question about an announced plan/prediction based on evidence. Both ''will'' and ''going to'' are acceptable but ''going to'' emphasizes the evidential basis.','medium'),
  (cid,71,232,'gap_fill','Under what conditions _____ the initiative _____ (produce) _____ outcomes _____ (anticipate/passive), and what _____ (happen) if _____ key assumptions on which it _____ (base/passive) _____ (prove) incorrect?','is / going to produce / the / anticipated / is going to happen / the / is based / prove',NULL,'Complex interrogative with ''going to produce/happen'' + conditional clause.','hard'),
  (cid,71,233,'gap_fill','Despite _____ optimistic projections, _____ program _____ (not/deliver) its stated objectives unless _____ implementation capacity _____ (strengthen/passive) significantly and _____ resource allocation _____ (restructure/passive) to _____ (reflect) actual priorities.','the / the / is not going to deliver / the / is strengthened / the / is restructured / reflect',NULL,'Negative ''going to'' + conditional unless clause.','hard'),
  (cid,71,234,'gap_fill','_____ the transition _____ (prove) as smooth as _____ proponents _____ (claim), or _____ stakeholders _____ (face) _____ period of significant disruption that _____ (require) _____ more robust support mechanisms than _____ (currently/plan/passive)?','Is / going to prove / the / claim / are stakeholders going to face / a / will require / the / are currently planned',NULL,'Interrogative ''is going to prove'' + alternative ''are going to face.''','hard'),
  (cid,71,235,'gap_fill','Without _____ sustained investment that _____ span multiple electoral cycles, _____ long-term objectives _____ (not/achieve/passive) — _____ precisely _____ risk that _____ critics _____ (warn) about.','the / will / the / are not going to be achieved / this is / the / the / are warning',NULL,'Negative ''going to be achieved'' (passive) + current warning rhetorical structure.','hard'),
  (cid,71,236,'gap_fill','Whether _____ agreement _____ (hold) under _____ pressure of _____ implementation will depend critically on whether _____ parties _____ (demonstrate) _____ political will they _____ (commit) to in _____ public statements.','the / is going to hold / the / the / the / are going to demonstrate / the / committed / their',NULL,'''Going to hold/demonstrate'' in complex conditional/dependent clause structure.','hard'),

  -- BLOCK 72: Be going to em análise de política comparada
  (cid,72,237,'gap_fill','Both approaches _____ (require) significant institutional adaptation, but _____ decentralized model _____ (face) _____ greater challenge in _____ (ensure) _____ consistency of _____ outcomes across _____ diverse range of _____ implementing jurisdictions.','are going to require / the / is going to face / a / ensuring / the / the / a / implementing',NULL,'''Going to require/face'' for comparative policy analysis prediction.','medium'),
  (cid,72,238,'gap_fill','_____ centralized approach _____ (enable) _____ greater economies of _____ scale but _____ (sacrifice) _____ flexibility that _____ (allow) _____ locally tailored responses to _____ context-specific challenges.','The / is going to enable / the / scale / is going to sacrifice / the / allows / locally / context-specific',NULL,'''Going to enable/sacrifice'' for comparative tradeoff analysis.','medium'),
  (cid,72,239,'multiple_choice','Which sentence BEST uses ''be going to'' for comparative policy analysis?','Country A is going to implement mandatory carbon pricing while Country B is going to rely on voluntary sector agreements — the divergence in approaches is going to generate valuable comparative evidence.','[''Country A will implement carbon pricing while Country B relies on voluntary agreements.'',''Country A is going to implement mandatory carbon pricing while Country B is going to rely on voluntary sector agreements — the divergence in approaches is going to generate valuable comparative evidence.'',''Country A implements carbon pricing and Country B is going to use voluntary agreements.'',''Country A would implement carbon pricing while Country B relied on voluntary agreements.'']','Parallel ''going to implement / going to rely / going to generate'' for announced comparative policy choices and their expected evidential value.','medium'),
  (cid,72,240,'gap_fill','_____ Nordic model _____ (prove) more _____ (sustain/passive) in _____ long run not because it _____ (avoid) _____ difficult trade-offs but because it _____ (distribute) _____ costs and benefits of _____ adjustment more _____ equitably than _____ alternatives.','The / is going to prove / sustainable / the / avoids / the / is going to distribute / the / the / equitably / the',NULL,'''Going to prove/distribute'' for prediction about comparative institutional sustainability.','hard'),
  (cid,72,241,'gap_fill','As _____ two systems _____ (converge) under _____ pressure of _____ shared external challenges, _____ differences that _____ (once/define) _____ them _____ (matter) less than _____ shared structural features that _____ (determine) _____ capacity to _____ (adapt).','the / converge / the / the / the / once defined / are going to matter / the / will determine / their / adapt',NULL,'''Are going to matter'' for evidence-based prediction about converging systems.','hard'),
  (cid,72,242,'gap_fill','Neither model _____ (prove) definitively superior — each _____ (demonstrate) _____ strengths and _____ (reveal) _____ limitations under _____ different conditions, and _____ (be) precisely _____ variation that _____ (make) _____ comparative analysis valuable.','is going to prove / is going to demonstrate / its / reveal / its / different / it is / this / makes / the',NULL,'''Going to prove/demonstrate'' in negative + parallel structure for comparative conclusion.','hard'),

  -- BLOCK 73: Be going to em TOEFL Writing — argumentação complexa
  (cid,73,243,'production','[TOEFL Writing — 200 words] Write a paragraph arguing that a specific policy is going to fail, using evidence-based ''be going to.''','',NULL,'The proposed universal basic income pilot program is going to fail to achieve its stated objectives for reasons that are evident from the design of the program itself and from the evidence accumulated in similar experiments elsewhere. The benefit level is going to prove insufficient to meaningfully reduce economic insecurity: at the proposed amount, recipients are going to remain below the poverty line, and the income supplement is going to be clawed back as earnings increase at a rate that is going to create significant work disincentives for those in the lower earnings range. The funding mechanism is going to generate political opposition that is going to make the program''s continuation beyond the pilot phase highly uncertain — the proposed tax on financial transactions is going to face legal challenges and is going to encourage the relocation of financial activity to lower-tax jurisdictions. The administrative architecture is going to create new bureaucratic complexity rather than simplifying the existing system, contradicting one of the program''s central rationales. Advocates of UBI are going to argue that these problems are going to be addressable through design modifications, but the evidence from this pilot is going to demonstrate that the political economy of a genuinely transformative UBI is going to prove far more challenging than its proponents have acknowledged.','hard'),
  (cid,73,244,'production','[TOEFL Writing — 200 words] Write a paragraph predicting what is going to happen to democracy globally over the next decade.','',NULL,'The trajectory of democracy over the next decade is going to be shaped by the interaction of several powerful forces pulling in different directions, and any confident prediction about the net direction of change requires acknowledging the deep uncertainty that characterizes this domain. The structural pressures that are going to challenge democratic governance are substantial: the concentration of economic power in a small number of technology platforms is going to undermine the information environments on which democratic deliberation depends; rising inequality is going to erode the social trust and sense of shared stake in common institutions that democratic systems require; and the complexity of the global challenges that governments are going to face is going to strain the capacity of democratic systems to make the kinds of long-term, technically complex decisions that climate change and other structural transformations are going to demand. At the same time, the forces working in democracy''s favor are not negligible: the authoritarian alternatives are going to continue to demonstrate their own severe limitations in generating legitimate governance and sustainable development; civil society is going to remain resilient and innovative in ways that are going to create new forms of democratic participation; and the demand for accountability and protection of rights that democratic systems are uniquely positioned to provide is going to remain powerful even in contexts where formal democratic institutions are under pressure.','hard'),
  (cid,73,245,'production','[TOEFL Writing — 200 words] Write a conclusion for an essay on what global health governance is going to require.','',NULL,'The analysis developed in this essay suggests that effective global health governance is going to require a more fundamental transformation than incremental reform of existing institutions can deliver. The COVID-19 pandemic demonstrated with devastating clarity that the current system — fragmented, under-resourced, and dependent on voluntary compliance by sovereign states — is going to be inadequate for managing the health threats that a more interconnected and ecologically stressed world is going to generate. What is going to be needed is a governance architecture that combines the legitimate authority to set binding standards and coordinate responses with the technical capacity to detect and characterize threats rapidly and the financial resources to ensure that response capacity is distributed equitably rather than concentrated in wealthy nations. Building this architecture is going to require political commitments that governments have historically been reluctant to make, because it is going to require accepting constraints on national sovereignty in a domain that touches directly on population welfare and security. The experience of the pandemic, however, has demonstrated what the alternative is going to cost. The question is not whether global health governance is going to need to be strengthened — that much is clear — but whether the political will to do so is going to emerge before or only after the next catastrophic failure makes the need undeniable once again.','hard'),

  -- BLOCK 74: Be going to — estruturas condicionais avançadas
  (cid,74,246,'gap_fill','Unless _____ international community _____ (take) _____ more coordinated approach, _____ individual national efforts, however well-intentioned, _____ (not/sufficient/prove) to _____ (address) _____ challenges that _____ (inherently/transboundary) in _____ nature.','the / takes / a / the / are not going to prove sufficient / address / the / are inherently transboundary / their',NULL,'''Unless'' + negative ''going to prove sufficient'' for conditional policy argument.','hard'),
  (cid,74,247,'gap_fill','Should _____ reform _____ (delay) further, _____ window of opportunity _____ (close) — _____ political conditions that _____ (currently/make) _____ change possible _____ (not/persist) indefinitely.','the / be delayed / the / is going to close / the / are currently making / the / are not going to persist',NULL,'''Going to close/persist'' for conditional urgency argument.','hard'),
  (cid,74,248,'gap_fill','Even if _____ most optimistic projections _____ (prove) correct, _____ transition _____ (require) _____ level of sustained effort and _____ resource commitment that _____ (test) _____ resilience of _____ institutions involved; if they _____ (prove) overly optimistic, _____ challenges _____ (be) substantially greater.','the / prove / the / is going to require / a / the / is going to test / the / the / prove / the / are going to be',NULL,'''Going to require/test/be'' in complex conditional layered structure.','hard'),
  (cid,74,249,'gap_fill','_____ success _____ (hinge) on whether _____ stakeholders who _____ (currently/resist) _____ reforms _____ (persuade/passive) that _____ costs of _____ status quo _____ (ultimately/prove) higher than _____ costs of _____ adaptation they _____ (oppose).','The / is going to hinge / the / are currently resisting / the / are going to be persuaded / the / the / are going to ultimately prove / the / the / are opposing',NULL,'''Going to hinge/be persuaded/prove'' for complex causal dependency.','hard'),
  (cid,74,250,'gap_fill','Provided that _____ conditions _____ (meet/passive) and _____ necessary resources _____ (make available/passive), _____ program _____ (deliver) on _____ promise — but _____ (be) _____ significant assumptions to _____ (build) _____ policy on.','the / are met / the / are made available / the / is going to deliver / its / these are / significant / build / a',NULL,'''Going to deliver'' in ''provided that'' conditional + ''these are significant assumptions'' comment.','hard'),
  (cid,74,251,'gap_fill','Whether _____ initiative _____ (achieve) _____ transformative impact or merely _____ (produce) _____ marginal improvements _____ (depend) on decisions _____ (make/passive) in _____ next twelve to eighteen months.','the / is going to achieve / a / produce / the / is going to depend / made / the',NULL,'''Going to achieve/depend'' in binary outcome conditional analysis.','hard'),
  (cid,74,252,'gap_fill','In _____ absence of _____ clear _____ enforcement mechanism, _____ agreement _____ (function) largely as _____ statement of _____ intent — _____ (remain) to _____ (see) whether _____ parties _____ (treat) it as _____ binding commitment or _____ aspirational declaration.','the / a / enforcement / the / is going to function / a / intent / it remains / see / the / are going to treat / a / an',NULL,'''Going to function/treat'' for prediction about agreement implementation without enforcement.','hard'),

  -- BLOCK 75: TOEFL Reading — be going to em textos complexos
  (cid,75,253,'multiple_choice','[TOEFL Reading] ''The organization is going to face mounting pressure from member states unless it demonstrates tangible results within the next fiscal year.'' What does this communicate?','A concrete, evidence-based prediction about institutional pressure tied to a performance condition.','[''A past event'',''A spontaneous decision'',''A concrete, evidence-based prediction about institutional pressure tied to a performance condition.'',''A hypothetical that is unlikely to occur'']','''Is going to face'' = evidence-based prediction; ''unless'' ties it to a performance condition.','medium'),
  (cid,75,254,'gap_fill','[TOEFL Reading] ''_____ sector _____ (undergo) _____ fundamental restructuring as _____ legacy players _____ (find) their traditional business models _____ (challenge/passive) by _____ new entrants who _____ (not/bound) by _____ same _____ regulatory constraints.'' Best forms?','The / is going to undergo / a / the / find / challenged / the / are not going to be bound / the / same',NULL,'''Going to undergo/bound'' for sector transformation prediction.','hard'),
  (cid,75,255,'gap_fill','[TOEFL Reading] ''_____ combination of _____ demographic pressure and _____ fiscal constraint _____ (force) _____ difficult choices about _____ scope and _____ generosity of _____ public services that _____ (not/possible) to _____ (defer) _____ indefinitely.'' Best forms?','The / the / the / is going to force / the / the / the / the / are not going to be possible / defer / indefinitely',NULL,'''Going to force/not be possible'' for evidence-based fiscal pressure prediction.','hard'),
  (cid,75,256,'gap_fill','[TOEFL Reading] ''Whether _____ technology _____ (prove) _____ transformative force its proponents _____ (claim) or _____ (fall) short of _____ expectations _____ (set/passive) by _____ early enthusiasm _____ (remain) one of _____ most consequential open questions in _____ field.'' Best forms?','the / is going to prove / the / claim / fall / the / set / the / remains / the / the',NULL,'''Going to prove/fall'' in alternative embedded question structure.','medium'),

  -- BLOCK 76: TOEFL Speaking — be going to avançado
  (cid,76,257,'production','[TOEFL Speaking — 60s] A reading outlines what a new international agreement is going to require of signatory states. Summarize.','',NULL,'The reading describes a landmark international agreement that is going to impose significantly more demanding obligations on signatory states than previous frameworks in this area. According to the reading, states that ratify the agreement are going to be required to submit detailed national action plans within eighteen months of ratification, specifying the specific measures they are going to adopt to meet their commitments. These plans are going to be subject to independent technical review, and states are going to be obligated to respond to the findings of these reviews within a specified timeframe. The agreement also establishes a compliance mechanism: states that are going to fall short of their commitments are going to be required to explain the reasons for the gap and present a remediation plan. The reading notes that the agreement is going to be financed through a combination of assessed contributions from developed-country parties and voluntary contributions, and that a capacity-building fund is going to provide technical and financial support to developing-country parties that are going to face particular challenges in meeting their obligations. The reading concludes by noting that whether the agreement is going to prove transformative or merely symbolic is going to depend critically on how seriously the major parties are going to treat the implementation and review obligations they are going to be assuming.','hard'),
  (cid,76,258,'production','[TOEFL Speaking — 45s] Contrast what two different economic approaches are going to produce as outcomes.','',NULL,'The reading presents two competing economic approaches, and the professor''s lecture elaborates on what each is going to produce as outcomes. According to the reading, the supply-side approach is going to stimulate investment and productivity growth by reducing the tax and regulatory burden on businesses, though critics argue that it is going to disproportionately benefit higher-income groups. The demand-side approach, by contrast, is going to boost consumption and employment in the short term through public investment and redistribution, though its proponents acknowledge that it is going to require higher levels of public debt. The professor argues that the empirical evidence suggests neither approach is going to prove universally superior — the approach that is going to work better is going to depend substantially on the specific macroeconomic conditions a country is facing. In a recession with high unemployment, demand stimulus is going to be more effective; in an economy near full employment, supply-side reforms are going to have a stronger impact on long-term growth. The professor concludes that the framing of the debate as a binary choice between the two approaches is going to mislead policymakers who are going to need to draw on both toolkits in a context-sensitive way.','hard'),

  -- BLOCK 77: TOEFL Writing — sínteses finais com be going to
  (cid,77,259,'production','[TOEFL Writing — 200 words] Write an introductory paragraph for an essay on what the energy transition is going to mean for developing economies.','',NULL,'The global energy transition away from fossil fuels is going to have profoundly differentiated consequences for developing economies, and understanding these differentiated impacts is going to be essential for designing the international support frameworks that are going to determine whether the transition is going to open new development pathways or impose additional burdens on countries that are already facing severe resource constraints. For some developing economies — particularly those with abundant renewable resources and the technical and financial capacity to exploit them — the transition is going to represent a significant economic opportunity: the ability to generate cheap, clean domestic energy is going to reduce import bills, lower production costs, and potentially create new export opportunities in green hydrogen and other renewable energy products. For others — particularly the fossil fuel exporters among developing countries, many of which have organized their fiscal systems around hydrocarbon revenues — the transition is going to create severe adjustment challenges as the demand for their primary export commodity is going to decline. For the majority of developing countries that are neither renewable energy exporters nor major fossil fuel producers, the net effect is going to depend substantially on how quickly renewable technology costs continue to fall and on whether international finance is going to be available to fund the infrastructure investments that are going to be necessary for a rapid transition. This essay is going to examine each of these cases in turn before drawing conclusions about the policy implications.','hard'),
  (cid,77,260,'production','[TOEFL Writing — 200 words] Write a paragraph on what artificial intelligence is going to mean for higher education.','',NULL,'Artificial intelligence is going to transform higher education in ways that are going to challenge fundamental assumptions about what universities are for, how learning happens, and what credentials are going to signify in a world where AI systems can perform many of the tasks that higher education has historically prepared students to do. The most immediate impact is going to be on assessment: as AI tools become capable of producing the kinds of written analysis that university assignments have traditionally required, institutions are going to be forced to redesign their assessment practices in ways that are going to require demonstration of capabilities that AI cannot replicate — original empirical research, complex collaborative problem-solving, nuanced interpersonal communication, and the kind of judgment that comes from embodied experience. The lecture and reading model of knowledge transmission that remains dominant in many institutions is going to become increasingly difficult to justify as AI tutoring systems become capable of delivering personalized instruction at scale and at a fraction of the cost of in-person teaching. What is going to survive — and potentially flourish — is the university''s function as a community of inquiry, a space for the kind of collaborative intellectual formation that is going to remain distinctively human and that AI is going to be able to support but not replace. Institutions that are going to adapt successfully are those that are going to lean into this function rather than defending the information-transmission model that is going to be most thoroughly disrupted.','hard'),
  (cid,77,261,'production','[TOEFL Writing — 200 words] Conclude an essay on what the rise of multipolarity is going to mean for global governance.','',NULL,'The transition to a multipolar international order is going to test the resilience of the multilateral institutions and norms that have structured global governance since 1945 in ways that are going to require both adaptation and, in some cases, fundamental reconceptualization. The institutions built in the postwar period were designed by and for a world in which Western powers, and above all the United States, were going to set the terms of international cooperation; a world in which several major powers with genuinely different visions of legitimate international order are going to exercise comparable weight is going to require institutional arrangements that can accommodate this diversity without collapsing into paralysis or competition. The most important question is not whether multilateralism is going to survive — the shared challenges that require coordinated responses are going to remain regardless of the distribution of power — but whether it is going to evolve in ways that are going to allow effective cooperation among powers that are going to disagree about fundamental questions of values and governance. The historical record offers limited grounds for optimism but does not support pessimism either: the capacity for pragmatic cooperation on shared interests even among ideologically divergent great powers has proved more durable than either utopian or dystopian predictions have suggested. Whether this capacity is going to prove adequate to the challenges of the coming decades is going to be one of the defining questions of our era.','hard'),

  -- BLOCK 78: Be going to — formas avançadas de gap fill
  (cid,78,262,'gap_fill','_____ scale of _____ investment _____ (require/passive) _____ (sustain) _____ transition _____ (dwarf) anything _____ that _____ public and private sectors _____ (mobilize) to date, _____ (raise) _____ fundamental question of _____ political feasibility.','The / the / going to be required / to sustain / the / is going to dwarf / anything / the / have mobilized / raising / a / political',NULL,'''Going to be required/dwarf'' in complex nominal + participial structure.','hard'),
  (cid,78,263,'gap_fill','What _____ (distinguish) this approach from _____ predecessors _____ (not/be) _____ novelty of _____ instruments _____ (employ/passive) but _____ rigor with which _____ (intend/passive) to _____ (implement) and _____ (evaluate) them.','is going to distinguish / its / is not going to be / the / the / employed / the / they are intended / implement / evaluate',NULL,'''Going to distinguish/be'' in contrastive academic sentence.','hard'),
  (cid,78,264,'gap_fill','_____ longer _____ (delay/passive) _____ adoption of _____ necessary measures, _____ more costly _____ eventual _____ adjustment _____ (prove) — _____ relationship between _____ delay and _____ cost _____ (be) non-linear, _____ (meaning) that _____ early action _____ (yield) _____ disproportionate returns.','The / is delayed / the / the / the / eventual / adjustment / is going to prove / the / between / delay / cost / is going to be / meaning / early / is going to yield / disproportionate',NULL,'''Going to prove/be/yield'' in complex causal chain about delay costs.','hard'),
  (cid,78,265,'gap_fill','It _____ (not/be) _____ technology that _____ (determine) _____ outcome but _____ political and institutional _____ choices that _____ (shape) _____ conditions under which _____ technology _____ (deploy/passive).','is not going to be / the / is going to determine / the / the / choices / are going to shape / the / the / is going to be deployed',NULL,'''Going to determine/shape/be deployed'' for technology governance argument.','hard'),
  (cid,78,266,'gap_fill','_____ (require) _____ genuine _____ multilateral _____ cooperation of _____ kind that _____ (elude) _____ international community on _____ previous occasions — and there _____ (be) _____ reason to _____ (believe) this time _____ (different/prove).','This is going to require / a / genuine / multilateral / the / has eluded / the / previous / is going to be / every / believe / is going to prove different',NULL,'''Going to require/be/prove different'' for skeptical assessment of multilateral cooperation.','hard'),

  -- BLOCK 79: TOEFL Writing — argumentos finais e parágrafos conclusivos
  (cid,79,267,'production','[TOEFL Writing — 200 words] Write a body paragraph arguing that current healthcare systems are going to be unable to meet future demand without structural reform.','',NULL,'Current healthcare systems in most high-income countries are going to be unable to meet the demand that aging populations are going to generate without structural reforms that go significantly beyond the incremental adjustments that governments have been making. The arithmetic of the challenge is straightforward: the share of the population over sixty-five is going to increase dramatically over the next three decades, and this group consumes healthcare resources at a rate several times higher than younger cohorts. Healthcare spending is going to need to increase as a share of GDP simply to maintain current service levels, and maintaining current service levels is going to prove insufficient as the accumulation of chronic conditions in aging populations is going to require more intensive and sustained care than the system is currently configured to provide. The workforce challenge is going to compound the fiscal challenge: the healthcare workforce is going to need to grow substantially at precisely the moment when the overall workforce is going to be shrinking, creating competition for workers that is going to drive up wages and costs. Without reforms that change how care is delivered — shifting resources toward prevention, primary care, and community-based services, and harnessing technology to extend the productivity of scarce clinical staff — healthcare systems are going to face a combination of cost pressures and quality deterioration that is going to be politically unsustainable.','hard'),
  (cid,79,268,'production','[TOEFL Writing — 200 words] Write a synthesis paragraph on what trade policy is going to look like in a world of great power competition.','',NULL,'Trade policy in an era of great power competition is going to look substantially different from the liberal trading order that dominated the post-Cold War period, and understanding what is going to replace it requires distinguishing between the dimensions of trade that are going to remain broadly open and those that are going to become increasingly subject to security-driven restrictions. In sectors where the major powers have identified strategic dependencies — semiconductors, critical minerals, pharmaceuticals, telecommunications equipment — trade is going to be increasingly shaped by national security calculations, with governments using subsidies, export controls, and import restrictions to build domestic capacity and reduce exposure to potential disruption. This strategic decoupling is going to be costly — it is going to sacrifice the efficiency gains from specialization and comparative advantage that free trade generates — but governments are going to judge these costs to be worth paying given the vulnerabilities that unrestricted trade has revealed. In sectors without clear security implications, trade is going to remain relatively open, because the economic costs of restricting it are going to be too high and the political coalitions supporting openness are going to remain strong. The result is going to be a bifurcated trading system — open in most sectors, restricted in strategic ones — that is going to require new governance frameworks that neither the WTO nor bilateral free trade agreements are well-equipped to provide.','hard'),
  (cid,79,269,'production','[TOEFL Writing — Final 200 words] Write a concluding paragraph for an essay on what sustainable development is going to require.','',NULL,'The conclusion that emerges from this analysis is that sustainable development — development that meets present needs without compromising the ability of future generations to meet theirs — is going to require a more fundamental transformation of the economic systems in which development is pursued than either the mainstream development community or political establishments in most countries have yet acknowledged. The incremental improvements in efficiency and the voluntary commitments that have characterized the dominant approach are going to prove insufficient: the scale of transformation required is going to demand not just better technologies and cleaner production processes, but a rethinking of the growth imperative itself and the development of metrics and institutions that are going to allow societies to measure and pursue wellbeing in ways that are going to be compatible with ecological sustainability. This is going to require difficult political choices about distribution, about the pace of consumption in high-income countries, and about the obligations that present generations are going to accept toward future ones. It is going to require new forms of international cooperation that are going to pool resources and technologies in ways that are going to allow developing countries to pursue wellbeing without replicating the ecological footprint of the development path that high-income countries have followed. Whether these transformations are going to prove achievable within the political systems and timeframes that matter is the defining question of our era, and how it is going to be answered will determine what kind of future is going to be possible.','hard'),

  -- BLOCK 80: Exercícios finais de consolidação
  (cid,80,270,'gap_fill','_____ question is not whether _____ transition _____ (happen) — _____ economic and environmental imperatives _____ (make) it _____ (inevitable) — but how quickly, how equitably, and with what consequences for _____ workers and _____ communities _____ (most/affect/passive).','The / the / is going to happen / the / are going to make / it inevitable / the / the / most affected',NULL,'''Going to happen/make inevitable'' in concessive ''not whether... but how'' structure.','hard'),
  (cid,80,271,'gap_fill','These _____ (be) precisely _____ kinds of _____ decisions that _____ (shape) _____ long-term trajectory and that _____ (not/reverse) easily once _____ (make/passive) — _____ (argue/passive) that _____ urgency with which they _____ (need) _____ (address/passive) can _____ (overstate/passive).','are going to be / the / the / are going to shape / the / are not going to be reversed / made / it is going to be argued / the / need / to be addressed / cannot be overstated',NULL,'Complex chain of ''going to be/shape/not be reversed/be argued'' for policy urgency.','hard'),
  (cid,80,272,'gap_fill','What _____ (distinguish) _____ successful cases from _____ failures _____ (not/be) _____ presence or _____ absence of _____ resources or _____ technical capacity but _____ quality of _____ institutions that _____ (govern) _____ process and _____ commitment of _____ leadership that _____ (drive) it.','is going to distinguish / the / the / is not going to be / the / the / the / the / the / the / govern / the / the / the / drives',NULL,'''Going to distinguish/not be'' for institutional comparative analysis conclusion.','hard'),
  (cid,80,273,'gap_fill','_____ reforms _____ (require) _____ long-term commitment that _____ (extend) beyond _____ electoral cycle — _____ (be) _____ political challenge, since _____ governments _____ (naturally/plan) to _____ horizon of _____ next election and _____ (not/easily/commit) to _____ costs whose _____ benefits _____ (accrue) to _____ future _____ administrations.','These / are going to require / a / extends / the / this is going to be / a / the / naturally plan / the / are not easily going to commit / the / whose / are going to accrue / future',NULL,'''Going to require/be/accrue'' in political economy analysis of long-term reform.','hard'),
  (cid,80,274,'gap_fill','If _____ analysis _____ (correct/prove), _____ consequences _____ (be) profound — not just for _____ immediate beneficiaries of _____ program but for _____ broader social compact that _____ (govern) _____ relationship between _____ citizens and _____ state.','this / proves correct / the / are going to be / the / the / the / the / governs / the / the / the',NULL,'''Going to be'' for conditional profound consequences of analytical prediction.','hard'),
  (cid,80,275,'gap_fill','_____ institutional design that _____ (prove) adequate to _____ demands of _____ twenty-first century _____ (require) not _____ reproduction of _____ past _____ arrangements but _____ creative _____ (synthesis) of _____ lessons _____ (learn/passive) from both _____ successes and _____ failures of _____ existing models.','The / is going to prove / the / the / is going to require / the / the / past / a / creative / synthesis / the / learned / the / the / the',NULL,'''Going to prove/require'' for institutional design normative conclusion.','hard'),
  (cid,80,276,'gap_fill','_____ success of _____ endeavor _____ (depend) on _____ willingness of _____ actors to _____ (subordinate) _____ short-term interests to _____ longer-term collective _____ good — _____ (be), historically, _____ condition that _____ (prove) _____ difficult to _____ (sustain).','The / the / is going to depend / the / all / subordinate / their / a / a / this is going to be / historically / a / has proved / difficult / sustain',NULL,'''Going to depend/be'' for collective action problem analysis conclusion.','hard'),

  -- BLOCK 81: Exercícios finais — gap fill e production
  (cid,81,277,'gap_fill','_____ demographic _____ (shift) _____ (reshape) _____ political _____ landscape in ways that _____ (favor) _____ parties and _____ candidates who _____ (speak) most _____ effectively to _____ concerns of _____ aging _____ electorate.','These / shifts / are going to reshape / the / political / are going to favor / the / those / speak / those / the / an / aging',NULL,'''Going to reshape/favor'' for demographic electoral analysis.','hard'),
  (cid,81,278,'gap_fill','Neither _____ technological _____ optimism nor _____ political _____ pessimism _____ (serve) _____ well as _____ guide to _____ action — what _____ (require/passive) _____ (be) _____ clear-eyed _____ (assess) of _____ both _____ opportunities and _____ constraints that _____ (shape) _____ options available.','the / optimism / the / pessimism / is going to serve / us / a / the / is going to be required / is going to be / a / clear-eyed / assessment / both / the / the / shape / the',NULL,'''Going to serve/be required/be'' for epistemological conclusion about analysis.','hard'),
  (cid,81,279,'production','[TOEFL Writing — 200 words] Write a paragraph arguing that current education systems are going to need to change fundamentally to prepare students for an AI-driven economy.','',NULL,'Education systems as currently constituted are going to be inadequate for preparing students for the economic and social environment that artificial intelligence is going to create, and the gap between what schools are going to need to deliver and what they are currently designed to provide is going to widen rapidly over the coming decade. The curriculum emphasis on knowledge retention and the reproduction of information in standardized formats is going to become increasingly misaligned with the demands of an economy in which AI is going to be able to perform these functions faster, more accurately, and at lower cost than human workers. What students are going to need — and what education systems are going to have difficulty delivering without fundamental redesign — is the capacity for creative problem-framing, for working effectively alongside AI tools, for exercising judgment in ambiguous and novel situations, and for collaborating productively with other humans in ways that leverage the distinctively human capacities that are going to remain most valuable. Assessment systems are going to need to change profoundly, because the written essay and the standardized test are going to be undermined as valid measures of student capability once AI tools are going to be freely available to assist in their completion. Teacher education and professional development are going to need to equip educators with the understanding of AI that is going to be essential for redesigning learning experiences in ways that are going to prepare rather than merely credential students. These are going to be difficult changes to make, but they are going to be necessary.','hard'),
  (cid,81,280,'production','[TOEFL Writing — 200 words] Write a final synthesis on what successful climate governance is going to require.','',NULL,'Successful climate governance is going to require the alignment of several elements that have historically proved difficult to combine: technical effectiveness, political legitimacy, economic efficiency, and distributional justice. Technical effectiveness demands that the policies adopted are actually going to reduce emissions at the scale and pace required by the physical science — not in projections prepared to satisfy political requirements, but in the real-world performance of the systems they are going to shape. Political legitimacy requires that the process by which climate policies are designed and implemented is going to be perceived as fair and participatory by the populations that are going to bear the costs of transition, without which the democratic backlash that has already derailed several promising policy experiments is going to continue to undermine progress. Economic efficiency demands that the policies adopted are going to achieve emissions reductions at the lowest possible cost, preserving resources for other priorities and maintaining the economic dynamism that is going to fund the investments required. Distributional justice requires that the costs and benefits of climate action are going to be shared in ways that do not impose disproportionate burdens on those who are least responsible for the problem and most vulnerable to its consequences — both within countries and between developed and developing nations. Building governance systems that are going to satisfy all four of these requirements simultaneously is going to be extraordinarily difficult, but there is no path to effective climate governance that is going to succeed if any one of them is going to be consistently neglected.','hard'),

  -- BLOCK 82: Exercícios de múltipla escolha e gap fill finais
  (cid,82,281,'multiple_choice','Which sentence MOST precisely uses ''be going to'' to signal an evidence-based institutional prediction?','Given the structural pressures documented in this analysis, the institution is going to face a legitimacy crisis unless it undertakes fundamental reform.','[''The institution will face a legitimacy crisis unless it reforms.'',''Given the structural pressures documented in this analysis, the institution is going to face a legitimacy crisis unless it undertakes fundamental reform.'',''The institution might face a legitimacy crisis if it does not reform.'',''The institution would face a legitimacy crisis without reform.'']','''Is going to face'' + ''given the structural pressures documented'' = evidence-based prediction grounded in prior analysis.','medium'),
  (cid,82,282,'multiple_choice','In an academic conclusion, which is the MOST EFFECTIVE use of ''be going to''?','The evidence examined in this paper demonstrates that current approaches are going to prove insufficient and that the scale of reform required is going to demand political commitments that governments have yet to make.','[''Current approaches will be insufficient and require political commitments.'',''The evidence suggests current approaches might prove insufficient.'',''The evidence examined in this paper demonstrates that current approaches are going to prove insufficient and that the scale of reform required is going to demand political commitments that governments have yet to make.'',''Current approaches are insufficient and demand political commitments.'']','Double ''going to prove/demand'' grounded in ''evidence examined'' = strong evidential prediction in academic conclusion.','hard'),
  (cid,82,283,'gap_fill','_____ transition _____ (not/be) _____ painless one — _____ (require) _____ sacrifices and _____ adjustments that _____ (test) _____ resilience of _____ institutions and _____ patience of _____ populations. But _____ alternative — _____ continuation of _____ current trajectory — _____ (prove) _____ far more _____ costly.','The / is not going to be / a / it is going to require / sacrifices / are going to test / the / the / the / the / the / the / the / is going to prove / far / costly',NULL,'''Going to be/require/test/prove'' in balanced cost-benefit rhetorical structure.','hard'),
  (cid,82,284,'gap_fill','As _____ (this/show/analysis), _____ question is not _____ technical but _____ political — _____ (not/be) _____ matter of what _____ (possible) but of what _____ (choose/passive) and by whom.','this analysis has shown / the / not / technical / political / it is not going to be / a / is possible / is going to be chosen',NULL,'''Going to be'' in normative political economy conclusion.','hard'),
  (cid,82,285,'gap_fill','_____ (conclude), _____ framework _____ (advance/passive) here _____ (offer) _____ more _____ analytically _____ rigorous and _____ politically _____ realistic path forward than _____ (currently/available) alternatives, though _____ (acknowledge) that its _____ (implement) _____ (face) _____ formidable _____ challenges.','To conclude / the / advanced / is going to offer / a / more / analytically / rigorous / politically / realistic / the currently available / we acknowledge / implementation / is going to face / formidable',NULL,'''Going to offer/face'' in academic conclusion with concession.','hard'),

  -- BLOCK 83: Exercícios finais de produção
  (cid,83,286,'production','[TOEFL Writing — 200 words] Write a paragraph on what is going to be required to achieve genuine gender equality.','',NULL,'Achieving genuine gender equality is going to require addressing structural barriers that are going to remain deeply resistant to change even as formal legal equality has been substantially achieved in most high-income countries. The persistence of gender pay gaps, even among workers with comparable qualifications and experience, is going to require interventions that go beyond anti-discrimination law to address the occupational segregation that channels women into lower-paid sectors, the care responsibilities that disproportionately constrain women''s labor market participation, and the implicit biases in hiring and promotion decisions that explicit rules are going to be insufficient to eliminate. Progress in formal employment is going to be undermined if the unpaid care economy continues to be distributed so unequally — genuine equality is going to require not just equal opportunity in paid work but a redistribution of care responsibilities that is going to demand changes in cultural norms, institutional arrangements, and economic incentives that are going to be slow to materialize. Political representation is going to require active measures beyond formal equal rights: evidence consistently demonstrates that without quotas or other affirmative mechanisms, representative bodies are going to remain significantly male-dominated. Genuine gender equality is going to be achieved not through any single policy intervention but through a sustained, multi-front effort that is going to need to be maintained over decades and that is going to require ongoing political will that has historically proved difficult to sustain.','hard'),
  (cid,83,287,'production','[TOEFL Writing — 200 words] Write a final conclusion on global economic governance reform.','',NULL,'The reform of global economic governance is going to be one of the defining governance challenges of the coming decades, and the outcome is going to shape the distribution of gains from the global economy, the management of shared risks, and the capacity of the international community to respond effectively to the crises that are going to emerge in an increasingly interconnected and volatile global system. The institutional architecture that needs to be reformed is going to resist change because those who have benefited most from existing arrangements are going to have the greatest influence over the reform process and are going to be the least motivated to support changes that might reduce their relative advantage. Reform is going to require building coalitions that include emerging economies in ways that give them genuine voice and decision-making power, not just the nominal inclusion that has characterized many previous reform efforts. It is going to require developing new frameworks for governing the digital economy, the green transition, and the health security challenges that are going to dominate the international economic agenda in ways that existing institutions were not designed to address. Whether global economic governance is going to prove adequate to these challenges is ultimately a political question, and the answer is going to depend on whether the major economies are going to find the combination of shared interest and political will that effective reform is going to demand.','hard'),
  (cid,83,288,'production','[TOEFL Speaking — 60s] What is going to be the most important challenge facing higher education institutions over the next decade? Use ''be going to'' throughout.','',NULL,'The most important challenge that higher education institutions are going to face over the next decade is going to be redefining their value proposition in a world where the technologies of knowledge transmission and credential verification are going to be fundamentally disrupted by artificial intelligence and digital platforms. The traditional university''s authority has rested on three pillars: it has been the primary place where advanced knowledge is created through research; it has been the most efficient vehicle for transmitting that knowledge to students; and it has been the gatekeeper that certifies through degrees that individuals have mastered relevant knowledge and skills. Each of these pillars is going to be challenged. Research is going to become increasingly collaborative and international, with the most significant work often happening in networks that span multiple institutions. Knowledge transmission is going to be disrupted by AI tutoring systems and online learning platforms that are going to provide personalized, high-quality instruction at a fraction of the cost of residential education. Credential verification is going to be challenged by alternative credentialing systems that are going to allow employers to assess skills more directly and efficiently than degree requirements have historically permitted. Institutions that are going to thrive are going to be those that lean into the dimensions of university education that technology is going to struggle to replicate — the formation of character, judgment, and relationships that happens through sustained engagement in a learning community — rather than defending the information-transmission model that is going to be most thoroughly disrupted.','hard'),
  (cid,83,289,'production','[TOEFL Writing — 200 words] Write a paragraph on what the future of work is going to look like.','',NULL,'The future of work is going to look sufficiently different from the present that many of the institutional arrangements, legal frameworks, and social norms that have governed employment relationships are going to need fundamental revision. The standard employment relationship — a full-time, indefinitely continuing contract between a single employer and employee, providing a predictable income, access to employer-sponsored benefits, and a degree of job security — is going to characterize a declining share of working relationships, as platform-mediated work, project-based employment, and self-employment are going to account for an increasing share of economic activity. This is going to create significant gaps in the social protection architecture, most of which was designed around the standard employment relationship and is going to provide inadequate coverage for workers in non-standard arrangements. The skills that are going to be most valuable are going to shift continuously as AI automates tasks that have required human expertise, and workers are going to need to retrain more frequently and more fundamentally than previous generations. Geographic flexibility is going to increase as remote work expands the pool of jobs accessible from any location, creating opportunities for workers in lower-cost areas but also intensifying competition in labor markets that were previously local. The institutions that are going to manage this transition successfully are going to be those that prioritize portability of benefits, invest in continuous retraining, and develop the regulatory frameworks needed to ensure that new forms of work are going to provide adequate security for the workers engaged in them.','hard'),
  (cid,83,290,'production','[TOEFL Writing — 200 words] Write a synthesis paragraph on what geopolitical competition is going to mean for technology governance.','',NULL,'The intensification of geopolitical competition is going to fundamentally reshape the governance of emerging technologies in ways that are going to have profound implications for innovation, access, and the potential for international cooperation on the management of shared risks. The dominant dynamic is going to be a fragmentation of the technology ecosystem along geopolitical lines, as the major powers pursue technology sovereignty and seek to reduce strategic dependence on rivals in sectors deemed critical to national security and economic competitiveness. This fragmentation is going to be most pronounced in the semiconductor supply chain, in telecommunications infrastructure, and in the data governance frameworks that are going to determine how information is stored, processed, and shared across borders. The costs of fragmentation are going to be substantial: it is going to sacrifice the efficiency gains from global specialization, it is going to slow the diffusion of beneficial technologies to lower-income countries that are going to be caught between competing systems, and it is going to impede the international coordination that managing the risks of powerful AI systems is going to require. Whether a degree of cooperation sufficient to manage the most severe technology risks is going to prove achievable despite geopolitical competition is one of the most consequential open questions in global governance, and the answer is going to be determined as much by political choices as by technological trajectories.','hard'),
  (cid,83,291,'gap_fill','In _____ final analysis, _____ (what) _____ (determine) _____ success or _____ failure of _____ initiative _____ (not/be) _____ quality of _____ design but _____ quality of _____ implementation — and _____ (be) _____ precisely _____ dimension that _____ (receive) _____ least _____ attention in _____ literature.','the / what / is going to determine / the / the / the / is not going to be / the / the / the / this is going to be / the / precisely / the / is going to receive / the / least / attention / the',NULL,'''Going to determine/be/receive'' in academic concluding meta-observation.','hard'),
  (cid,83,292,'gap_fill','_____ path forward _____ (not/be) _____ easy one, but _____ evidence _____ (suggest) that _____ combination of _____ political will, _____ institutional _____ innovation, and _____ sustained _____ investment _____ (sufficient/prove) to _____ (navigate) _____ transition successfully if _____ (mobilize/passive) with _____ urgency _____ moment _____ demands.','The / is not going to be / an / the / suggests / a / the / political / institutional / sustained / is going to prove sufficient / navigate / the / mobilized / the / the / demands',NULL,'''Going to be/prove sufficient'' in measured optimistic policy conclusion.','hard'),
  (cid,83,293,'gap_fill','These _____ (be) _____ questions that _____ (not/admit) of _____ simple _____ answers — they _____ (require) _____ sustained _____ engagement with _____ evidence, _____ willingness to _____ (revise) _____ assumptions in _____ light of _____ new information, and _____ commitment to _____ (pursue) _____ truth even when _____ (uncomfortable).','are going to be / the / are not going to admit / simple / answers / are going to require / sustained / engagement / the / the / revise / our / the / a / pursuing / the / uncomfortable',NULL,'''Going to be/admit/require/pursuing'' in epistemological conclusion about complex analysis.','hard'),
  (cid,83,294,'gap_fill','_____ (conclude) with _____ observation that _____ (apply) across _____ domains examined in _____ paper: _____ institutions that _____ (prove) most _____ resilient _____ (not/be) those that _____ (avoid) _____ pressure for _____ change but those that _____ (develop) _____ capacity to _____ (adapt) without _____ (lose) _____ core commitments that _____ (give) them _____ legitimacy.','We conclude / an / applies / the / this / the / prove / most / resilient / are not going to be / avoided / the / change / developed / the / adapt / losing / their / give / their',NULL,'''Going to prove/be/give'' in final institutional resilience conclusion.','hard'),
  (cid,83,295,'production','[TOEFL Writing — 200 words] Final synthesis: what is going to define the next era of global development?','',NULL,'The next era of global development is going to be defined by three interconnected transitions that are going to reshape the conditions under which countries are going to be able to improve human welfare. The first is the ecological transition: the imperative of decarbonizing the global economy while managing the adaptation to climate change that is already inevitable is going to constrain the development pathways available to all countries and is going to require new forms of international cooperation and finance to ensure that the costs of transition are going to be distributed equitably. The second is the technological transition: artificial intelligence and automation are going to transform the economic basis of development in ways that are going to create new opportunities for countries that can harness them and serious risks of marginalization for those that cannot. The third is the geopolitical transition: the shift to a multipolar world is going to complicate the multilateral cooperation that the first two transitions are going to demand, creating a governance gap at precisely the moment when effective global governance is going to be most needed. How these three transitions are going to interact, and whether the international community is going to develop the institutions and the political will to manage them effectively, is going to determine what kind of world is going to emerge over the coming decades. The choices made now are going to be the ones that matter most.','hard'),
  (cid,83,296,'gap_fill','_____ (succeed), _____ reform _____ (need) to _____ (address) _____ both _____ symptoms and _____ root causes — a distinction that _____ (often/collapse) in _____ political discourse, where _____ (address) _____ visible _____ problem _____ (confused/passive) with _____ (solve) it.','To succeed / the / is going to need / address / both / the / the / is going to often be collapsed / the / addressing / a / visible / problem / is going to be confused / solving',NULL,'''Going to need/be collapsed/be confused'' for meta-political analysis of reform discourse.','hard'),
  (cid,83,297,'gap_fill','Whether _____ partnership _____ (prove) _____ durable or merely _____ (dissolve) when _____ interests diverge _____ (depend) on whether _____ (build/passive) on _____ genuine shared interests or _____ on _____ temporary convergence that _____ (evaporate) when circumstances _____ (change).','the / is going to prove / durable / dissolve / the / is going to depend / it has been built / the / or / a / is going to evaporate / change',NULL,'''Going to prove/depend/evaporate'' for partnership durability analysis.','hard'),
  (cid,83,298,'gap_fill','_____ lesson that _____ (emerge) from _____ comparative analysis _____ (be) _____ (humbling) one: _____ solutions that _____ (work) in one context _____ (not/automatically/transfer) to _____ another, and _____ (require) careful _____ (adapt) to _____ local _____ conditions that _____ (often/underestimate/passive) by _____ those _____ (advocate) for _____ universal _____ approaches.','The / is going to emerge / the / is going to be / a / humbling / work / are not going to automatically transfer / another / are going to require / adaptation / local / are often underestimated / those / advocating / universal',NULL,'''Going to emerge/be/transfer/require/underestimate'' for comparative policy epistemology.','hard'),
  (cid,83,299,'gap_fill','As _____ world _____ (navigate) _____ these transitions, _____ institutions that _____ (most/matter) _____ (not/be) necessarily _____ (most/powerful) or _____ (most/resource/passive) but those that _____ (most/legitimate/passive) in _____ eyes of _____ those whose _____ cooperation _____ (most/need/passive).','the / navigates / these / the / are going to matter most / are not going to be / the most powerful / the most resourced / are going to be most legitimated / the / those / cooperation / is going to be most needed',NULL,'''Going to matter/be/legitimated/needed'' in final institutional legitimacy conclusion.','hard'),
  (cid,83,300,'production','[TOEFL Writing — Final 200 words] Write a capstone conclusion on what transformative change is going to require in the twenty-first century.','',NULL,'Transformative change in the twenty-first century is going to require a combination of elements that are going to be individually necessary but collectively insufficient unless they are going to be brought together in ways that have historically proved extraordinarily difficult to achieve. The technical dimension — the knowledge, the technologies, the institutional designs — is going to be the easiest part: the challenge is not primarily one of knowing what needs to be done but of building the political and social conditions under which it is going to be possible to do it. This is going to require political leadership that is willing to articulate the long-term interest even when it is going to conflict with the short-term preferences of powerful constituencies. It is going to require institutional innovation that creates the organizational capacity to coordinate action at the scales that the challenges require. It is going to require civic engagement and public deliberation that builds the social legitimacy for the difficult choices that are going to need to be made. And it is going to require a degree of international cooperation that the current political environment is going to make extremely difficult but that the shared nature of the challenges is going to make absolutely necessary. None of this is going to be easy, and there is no guarantee that it is going to prove achievable. But the alternative — the continuation of current trajectories — is going to prove far more costly. The question is not whether transformative change is going to be needed. It is whether we are going to choose it before circumstances are going to force it upon us.','hard')

